def esc(x):return html.escape(str(x))
def source(path,label):
 return f'<a href="../../{path}">{label} ↗</a>'
def excerpt(title,value):return f'<details><summary>{title}</summary><pre>{esc(json.dumps(value,ensure_ascii=False,indent=2))}</pre></details>'
