def cite(keys):
    links=[]
    for key in keys.split(','):
        i,r=refmap[key.strip()]
        links.append(f'<a class="citation" href="#ref-{i}" title="{esc(r["title"])}">[{i}]</a>')
    return ' '.join(links)
rows=''.join(f'<tr><td>{esc(r["layer"])}</td><td>{esc(r["name"])}</td><td>{esc(r["description"])}</td><td>{cite(r["references"])}</td></tr>' for r in tax)
reference_items=[]
